"""Editor script: create the world materials in /Game/World (no game data; regenerated by this script)."""
# 0x30F960 / 0x31C790 / 0x17B980 / 0x1E4288
import os
import struct
import zlib

import unreal

PATH = "/Game/World"
assets = unreal.EditorAssetLibrary
mel = unreal.MaterialEditingLibrary
tools = unreal.AssetToolsHelpers.get_asset_tools()

ENC = "(lerp(1.055 * pow(max({x}, 0.0), 1.0 / 2.4) - 0.055, {x} * 12.92, step({x}, 0.0031308)))"
PS2_MAX = "(255.0 / 128.0)"

TERRAIN_SHADE = f"""
float3 t = {ENC.format(x='Tex')};
float a = LM.a * (255.0 / 128.0);
float3 c;
if (Mode < 0.5)      c = (t - LM.rgb) * a;
else if (Mode < 1.5) c = t * a;
else if (Mode < 2.5) c = t * {PS2_MAX};
else if (Mode < 3.5) c = LM.aaa;
else if (Mode < 4.5) c = float3(UV.xy, 0.0);
else                 c = float3(UV.zw * float2(8.0, 4.0) / 2.0, 0.0);
c = saturate(c);
return c;   // PS2 colour space: the GS value / 255 is the scene colour
"""
LIGHTMAP_UV = """
float2 l = Local;
if (SwapUV > 0.5) l = l.yx;
if (FlipU > 0.5) l.x = 1.0 - l.x;
if (FlipV > 0.5) l.y = 1.0 - l.y;
float2 texel = clamp(l * 8.0, 0.5, 7.5);
return Origin + texel / 8.0 * float2(1.0 / 128.0, 1.0 / 64.0);
"""
SCALE_SHADE = f"""
float3 t = {ENC.format(x='Tex')};
float3 c = saturate(t * Factor);
return c;   // PS2 colour space: the GS value / 255 is the scene colour
"""
PROP_SHADE = f"""
float3 t = {ENC.format(x='Tex')};
float3 c = saturate(t * VC.rgb * (255.0 / 128.0));
return c;   // PS2 colour space: the GS value / 255 is the scene colour
"""
# FUN_00200390 / 0x1E1F70
PROP_GS_ALPHA = """float at = min(floor((floor(A * 255.0 + 0.001) + 1.0) * 0.5), 128.0);
float av = floor(VA * 255.0 + 0.5);
return min(floor(at * av / 128.0), 255.0);
"""
GS_AREF = 1   # FUN_00200390
PROP_ATEST = f"return As > {GS_AREF}.0 ? 1.0 : 0.0;"
PROP_CORE = "return As >= 128.0 ? 1.0 : 0.0;"
PROP_BLEND = f"return (As > {GS_AREF}.0 && As < 128.0) ? As / 128.0 : 0.0;"
SOFT_DEPTH = "return (PD <= CD.r * 1.0005 + 0.5) ? 1.0 : 0.0;"
SOFT_DEPTH_CLIP = 1.0 / 256.0
MIP_LOD = "return On > 0.5 ? max(exp2(L) * log2(max(Depth, 1.0)) + K / 16.0, 0.0) : 0.0;"
CLEAR_SHADE = f"""
float3 c = saturate(C.rgb);
return c;   // PS2 colour space: the GS value / 255 is the scene colour
"""
DRAW_CLIP = "return (Depth <= DrawDistance ? 1.0 : 0.0) * Alpha;"
RIDER_LIGHT = f"""
float3 v = Ambient + saturate(dot(N, normalize(D0))) * C0 + saturate(dot(N, normalize(D1))) * C1
         + saturate(dot(N, normalize(D2))) * C2;
return clamp(v, 0.0, {PS2_MAX});
"""
# 0x318080
CHROME_UV = "return float2(N.x * R.x - N.y * U.x + N.z * F.x, -N.x * R.y + N.y * U.y - N.z * F.y);"
CHROME_SHADE = f"""
float3 t = {ENC.format(x='Tex')};
float3 e = {ENC.format(x='Env')};
float3 cb = saturate(t * V);
float3 ce = saturate(e * V);
return saturate(cb + (ce - cb) * (33.0 / 128.0));
"""
# 0x1364D0 / 0x1DCC10
RIDER_DEPTH = """float wp = dot(RootRel, F);
float w = dot(Rel, F);
if (Pull <= 0.0 || View.ViewToClip[3][3] >= 1.0 || wp - Pull < Near || wp > Far || !(w >= Near && w <= Far)) return float3(0.0, 0.0, 0.0);
float d = 1.0 / (wp - Pull) - 1.0 / wp;
float s = 1.0 / (1.0 + d * w);
return Rel * (s - 1.0);
"""
# 0x318080
RIDER_CLIP = """float w = dot(Rel, F);
if (Pull <= 0.0 || View.ViewToClip[3][3] >= 1.0) return 0.0;
if (!(w >= Near && w <= Far)) return 1.0;
float2 ndc = float2(View.ViewToClip[0][0] * dot(Rel, R), View.ViewToClip[1][1] * dot(Rel, U)) / w;
return (abs(ndc.x) <= Guard.x && abs(ndc.y) <= Guard.y) ? 0.0 : 1.0;
"""
RIDER_KEEP = """return Clip > 0.0 ? 0.0 : 1.0;
"""
GLOSS_UV = "return saturate(float2(N.x * R.x - N.y * U.x + N.z * F.x, -N.x * R.y + N.y * U.y - N.z * F.y));"
GLOSS_SHADE = f"""
float3 t = {ENC.format(x='Tex')};
float3 g = {ENC.format(x='Gloss')};
float3 cb = saturate(t * V);
float3 cg = saturate(g * V);
return saturate(cb + cg * Fix);
"""
PP_ENCODE = """
return saturate(max(Scene.rgb / View.PreExposure, 0.0) * Brightness);
"""

unreal.AssetRegistryHelpers.get_asset_registry().scan_paths_synchronous([PATH], True)


def connect(src, out, dst, inp):
    if not unreal.MaterialEditingLibrary.connect_material_expressions(src, out, dst, inp):
        raise RuntimeError(f"cannot connect {src.get_name()}.{out} -> {dst.get_name()}.{inp}")


def connect_prop(src, out, prop):
    if not unreal.MaterialEditingLibrary.connect_material_property(src, out, prop):
        raise RuntimeError(f"cannot connect {src.get_name()}.{out} -> {prop}")


def clear_expressions(m):
    """delete_all_material_expressions skips every other node per call (stale unconnected nodes piled up in the
    graphs): repeat until the graph is empty."""
    for _ in range(16):
        if unreal.MaterialEditingLibrary.get_num_material_expressions(m) == 0:
            return
        unreal.MaterialEditingLibrary.delete_all_material_expressions(m)


def fresh(name, cls, factory, recreate=False):
    """Reuse an existing asset (keeps references from track material instances valid), else create it.
    recreate: delete and create it anew (delete_all_material_expressions asserts !IsRooted on a VertexColor node;
    only for materials no instance references)."""
    full = f"{PATH}/{name}"
    if assets.does_asset_exist(full):
        if recreate:
            assets.delete_asset(full)
            return tools.create_asset(name, PATH, cls, factory)
        a = assets.load_asset(full)
        if isinstance(a, unreal.Material):
            clear_expressions(a)
        return a
    return tools.create_asset(name, PATH, cls, factory)


def expr(mat, cls, x, y, **props):
    e = mel.create_material_expression(mat, cls, x, y)
    for k, v in props.items():
        e.set_editor_property(k, v)
    return e


def custom(mat, x, y, code, out_type, inputs, desc):
    e = expr(mat, unreal.MaterialExpressionCustom, x, y)
    e.set_editor_property("code", code)
    e.set_editor_property("output_type", out_type)
    e.set_editor_property("description", desc)
    ins = []
    for n, _ in inputs:
        ci = unreal.CustomInput()
        ci.set_editor_property("input_name", n)
        ins.append(ci)
    e.set_editor_property("inputs", ins)
    for n, (src, out) in inputs:
        if src is not None:
            connect(src, out, e, n)
    return e


def coll(mat, mpc, name, x, y):
    return expr(mat, unreal.MaterialExpressionCollectionParameter, x, y, collection=mpc, parameter_name=name)


def _png(path, w, h, rgba):
    """Write a tiny uniform RGBA PNG (the editor's Python has no PIL)."""
    raw = b"".join(b"\0" + bytes(rgba) * w for _ in range(h))

    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    with open(path, "wb") as f:
        f.write(bytes([0x89]) + b"PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))


def default_lightmap():
    """Linear 4x4 default for the Lightmap parameter: RGB 0, alpha 0x80 (= 1.0, texture unchanged)."""
    name = "T_SSXLightmapNeutral"
    if not assets.does_asset_exist(f"{PATH}/{name}"):
        # staged in the project's Intermediate folder and imported with the legacy texture factory, so the asset's
        # import data holds only the relative source path (Interchange also stores the absolute one)
        stage = unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_intermediate_dir())
        png = os.path.join(stage, f"{name}.png")
        _png(png, 4, 4, (0, 0, 0, 128))
        task = unreal.AssetImportTask()
        for k, v in (("filename", png), ("destination_path", PATH), ("destination_name", name),
                     ("automated", True), ("replace_existing", True), ("save", False)):
            task.set_editor_property(k, v)
        unreal.SystemLibrary.execute_console_command(None, "Interchange.FeatureFlags.Import.PNG 0")
        tools.import_asset_tasks([task])
        unreal.SystemLibrary.execute_console_command(None, "Interchange.FeatureFlags.Import.PNG 1")
        os.remove(png)
    tex = unreal.load_asset(f"{PATH}/{name}")
    tex.set_editor_property("srgb", False)
    tex.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_VECTOR_DISPLACEMENTMAP)
    tex.set_editor_property("mip_gen_settings", unreal.TextureMipGenSettings.TMGS_NO_MIPMAPS)
    assets.save_asset(f"{PATH}/{name}", only_if_is_dirty=False)
    return tex


def tex_param(mat, name, x, y, linear=False, mip=None, clamp=False):
    """mip: None = hardware mip selection, or an expression output giving the explicit mip level."""
    e = expr(mat, unreal.MaterialExpressionTextureSampleParameter2D, x, y, parameter_name=name)
    if clamp:
        e.set_editor_property("sampler_source", unreal.SamplerSourceMode.SSM_CLAMP_WORLD_GROUP_SETTINGS)
    e.set_editor_property("texture", default_lightmap() if linear
                          else unreal.load_asset("/Engine/EngineResources/WhiteSquareTexture"))
    e.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_COLOR if linear
                          else unreal.MaterialSamplerType.SAMPLERTYPE_COLOR)
    if mip is not None:
        e.set_editor_property("mip_value_mode", unreal.TextureMipValueMode.TMVM_MIP_LEVEL)
        connect(mip[0], mip[1], e, "Level")
    return e


def mip_lod(mat, mpc, x, y):
    """The table's texture LOD as an explicit mip level from the pixel's view depth."""
    return (custom(mat, x, y, MIP_LOD, F1,
                   [("Depth", (expr(mat, unreal.MaterialExpressionPixelDepth, x - 300, y), "")),
                    ("On", (coll(mat, mpc, "MipLodOn", x - 300, y + 80), "")),
                    ("L", (coll(mat, mpc, "MipLodL", x - 300, y + 160), "")),
                    ("K", (coll(mat, mpc, "MipLodK", x - 300, y + 240), ""))], "MipLod"), "")


def new_material(name, two_sided=True, recreate=False):
    m = fresh(name, unreal.Material, unreal.MaterialFactoryNew(), recreate)
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_UNLIT)
    m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_MASKED)
    m.set_editor_property("two_sided", two_sided)
    return m


def finish(m):
    mel.recompile_material(m)
    assets.save_asset(m.get_path_name().split(".")[0], only_if_is_dirty=False)
    unreal.log(f"[ssx] created {m.get_path_name()}")


F1, F2, F3 = (unreal.CustomMaterialOutputType.CMOT_FLOAT1, unreal.CustomMaterialOutputType.CMOT_FLOAT2,
              unreal.CustomMaterialOutputType.CMOT_FLOAT3)


def clip(m, mpc, alpha_src):
    depth = expr(m, unreal.MaterialExpressionPixelDepth, -700, 500)
    dd = coll(m, mpc, "DrawDistance", -700, 600)
    one = expr(m, unreal.MaterialExpressionConstant, -700, 700, r=1.0)
    a = alpha_src if alpha_src is not None else (one, "")
    c = custom(m, -300, 550, DRAW_CLIP, F1, [("Depth", (depth, "")), ("DrawDistance", (dd, "")), ("Alpha", a)], "DrawClip")
    connect_prop(c, "", unreal.MaterialProperty.MP_OPACITY_MASK)


mpc = fresh("MPC_SSXWorld", unreal.MaterialParameterCollection, unreal.MaterialParameterCollectionFactoryNew())
old_scalars = {str(p.get_editor_property("parameter_name")): p for p in mpc.get_editor_property("scalar_parameters")}
old_vectors = {str(p.get_editor_property("parameter_name")): p for p in mpc.get_editor_property("vector_parameters")}
scalars = []
for n, v in (("DrawDistance", 1.0e9), ("LightmapMode", 0.0), ("LightmapSwapUV", 1.0), ("LightmapFlipU", 0.0),
             ("LightmapFlipV", 0.0), ("SkyAmbient", 1.992), ("MipLodOn", 0.0), ("MipLodL", 0.0), ("MipLodK", 0.0),
             ("Brightness", 1.0)):
    p = old_scalars.get(n) or unreal.CollectionScalarParameter()
    p.set_editor_property("parameter_name", n)
    p.set_editor_property("default_value", v)
    scalars.append(p)
mpc.set_editor_property("scalar_parameters", scalars)
cc = old_vectors.get("ClearColour") or unreal.CollectionVectorParameter()
cc.set_editor_property("parameter_name", "ClearColour")
cc.set_editor_property("default_value", unreal.LinearColor(0.0, 0.0, 0.0, 128.0 / 255.0))
mpc.set_editor_property("vector_parameters", [cc])
assets.save_asset(f"{PATH}/MPC_SSXWorld", only_if_is_dirty=False)

for name, masked, clipped in (("M_SSXTerrain", False, True), ("M_SSXTerrain_Masked", True, True),
                              ("M_SSXTerrainOpaque", False, False)):
    m = new_material(name)
    if not clipped:
        m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_OPAQUE)
    base = tex_param(m, "BaseTex", -1100, -200, mip=mip_lod(m, mpc, -1400, -500))
    uv1 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1500, 100, coordinate_index=1)
    uv2 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1500, 200, coordinate_index=2)
    lmuv = custom(m, -1250, 150, LIGHTMAP_UV, F2,
                  [("Local", (uv1, "")), ("Origin", (uv2, "")),
                   ("SwapUV", (coll(m, mpc, "LightmapSwapUV", -1500, 300), "")),
                   ("FlipU", (coll(m, mpc, "LightmapFlipU", -1500, 380), "")),
                   ("FlipV", (coll(m, mpc, "LightmapFlipV", -1500, 460), ""))], "LightmapUV")
    lm = tex_param(m, "Lightmap", -1000, 150, linear=True)
    connect(lmuv, "", lm, "UVs")
    lm4 = expr(m, unreal.MaterialExpressionAppendVector, -750, 150)
    connect(lm, "RGB", lm4, "A")
    connect(lm, "A", lm4, "B")
    uv4 = expr(m, unreal.MaterialExpressionAppendVector, -1250, 400)
    connect(uv1, "", uv4, "A")
    connect(uv2, "", uv4, "B")
    shade = custom(m, -400, 0, TERRAIN_SHADE, F3,
                   [("Tex", (base, "RGB")), ("LM", (lm4, "")), ("Mode", (coll(m, mpc, "LightmapMode", -750, 300), "")),
                    ("UV", (uv4, ""))], "TerrainShade")
    connect_prop(shade, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    if clipped:
        clip(m, mpc, (base, "A") if masked else None)
    finish(m)

PROP_KINDS = (("M_SSXProp", "plain"), ("M_SSXProp_Masked", "atest"), ("M_SSXPropOpaque", "opaque"),
              ("M_SSXProp_TranslucentCore", "core"), ("M_SSXProp_Translucent", "blend"))
for name, mode, two in [(n + sfx, md, t) for (n, md) in PROP_KINDS for sfx, t in (("", True), ("_TwoSided", True))]:
    m = new_material(name, two_sided=two)
    if mode == "opaque":
        m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_OPAQUE)
    elif mode == "blend":
        m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_TRANSLUCENT)
        m.set_editor_property("use_translucency_vertex_fog", False)
        m.set_editor_property("allow_translucent_custom_depth_writes", True)
        m.set_editor_property("opacity_mask_clip_value", SOFT_DEPTH_CLIP)
    else:
        m.set_editor_property("opacity_mask_clip_value", 0.5)
    base = tex_param(m, "BaseTex", -1000, -200, mip=mip_lod(m, mpc, -1400, -500))
    uv0 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1700, -200, coordinate_index=0)
    su = expr(m, unreal.MaterialExpressionScalarParameter, -1700, -100, parameter_name="UVScrollU", default_value=0.0)
    sv = expr(m, unreal.MaterialExpressionScalarParameter, -1700, 0, parameter_name="UVScrollV", default_value=0.0)
    suv = expr(m, unreal.MaterialExpressionAppendVector, -1500, -50)
    connect(su, "", suv, "A")
    connect(sv, "", suv, "B")
    uvs = expr(m, unreal.MaterialExpressionAdd, -1300, -150)
    connect(uv0, "", uvs, "A")
    connect(suv, "", uvs, "B")
    connect(uvs, "", base, "UVs")
    vc = expr(m, unreal.MaterialExpressionVertexColor, -750, 100)
    shade = custom(m, -400, 0, PROP_SHADE, F3, [("Tex", (base, "RGB")), ("VC", (vc, ""))], "PropVertexLight")
    connect_prop(shade, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    if mode in ("atest", "core", "blend"):
        gs_a = custom(m, -1000, 400, PROP_GS_ALPHA, F1, [("A", (base, "A")), ("VA", (vc, "A"))], "PropGsAlpha")
        code, desc = {"atest": (PROP_ATEST, "PropAlphaTest"), "core": (PROP_CORE, "PropCore"),
                      "blend": (PROP_BLEND, "PropBlend")}[mode]
        alpha = custom(m, -800, 400, code, F1, [("As", (gs_a, ""))], desc)
        if mode == "blend":
            depth = expr(m, unreal.MaterialExpressionPixelDepth, -700, 500)
            dd = coll(m, mpc, "DrawDistance", -700, 600)
            cd = expr(m, unreal.MaterialExpressionSceneTexture, -1000, 650, scene_texture_id=unreal.SceneTextureId.PPI_CUSTOM_DEPTH)
            front = custom(m, -800, 650, SOFT_DEPTH, F1, [("PD", (depth, "")), ("CD", (cd, "Color"))], "SoftDepth")
            vis = expr(m, unreal.MaterialExpressionMultiply, -550, 450)
            connect(alpha, "", vis, "A")
            connect(front, "", vis, "B")
            op = custom(m, -300, 550, DRAW_CLIP, F1, [("Depth", (depth, "")), ("DrawDistance", (dd, "")), ("Alpha", (vis, ""))],
                        "DrawClip")
            connect_prop(op, "", unreal.MaterialProperty.MP_OPACITY)
        else:
            clip(m, mpc, (alpha, ""))
    elif mode == "plain":
        clip(m, mpc, None)
    finish(m)

CROWD_UV = """
float idx = floor(UV1.x + 0.5);
float4 f = idx < 4 ? F0 : (idx < 8 ? F1 : (idx < 12 ? F2 : F3));
float j = idx - 4.0 * floor(idx / 4.0);
float fr = floor((j < 1 ? f.x : (j < 2 ? f.y : (j < 3 ? f.z : f.w))) + 0.5);
float2 cell = float2(fr - 4.0 * floor(fr / 4.0), floor(fr / 4.0));
return (cell + clamp(UV0, 0.5 / 128.0, 1.0 - 0.5 / 128.0)) / 4.0;
"""
def rgba_param(mat, name, x, y):
    """A vector parameter as one float4 (its bare output is RGB only)."""
    p = expr(mat, unreal.MaterialExpressionVectorParameter, x, y, parameter_name=name,
             default_value=unreal.LinearColor(0, 0, 0, 0))
    a = expr(mat, unreal.MaterialExpressionAppendVector, x + 200, y)
    connect(p, "", a, "A")
    connect(p, "A", a, "B")
    return a


